using System;
using System.Collections.Generic;
using System.Configuration;
using System.Data;
using System.Data.SqlClient;

namespace MyfschoolWeb.DataAccess
{
    /// <summary>
    /// Tiny ADO.NET helper for SQL Server database FSchoolDB. Parameterized queries only:
    /// never concatenate user input into the SQL text, pass it with SqlDb.P("@name", value).
    /// Connection string "FSchoolDb" comes from Web.config -> connections.config (generated by tools\gen-connection.ps1).
    /// </summary>
    public static class SqlDb
    {
        public static string ConnectionString
        {
            get
            {
                var cs = ConfigurationManager.ConnectionStrings["FSchoolDb"];
                if (cs == null || string.IsNullOrWhiteSpace(cs.ConnectionString))
                    throw new InvalidOperationException("Connection string 'FSchoolDb' is missing. Run tools\\gen-connection.ps1 to create connections.config.");
                return cs.ConnectionString;
            }
        }

        /// <summary>New parameter; null becomes DBNull.</summary>
        public static SqlParameter P(string name, object value)
        {
            return new SqlParameter(name, value ?? DBNull.Value);
        }

        public static SqlConnection Open()
        {
            var c = new SqlConnection(ConnectionString);
            c.Open();
            return c;
        }

        /// <summary>Run a SELECT and return all rows as a DataTable (good for GridView/Repeater DataSource).</summary>
        public static DataTable Query(string sql, params SqlParameter[] ps)
        {
            using (var c = Open()) return QueryOn(c, null, sql, ps);
        }

        /// <summary>Run a SELECT and map each row with <paramref name="map"/> (e.g. r =&gt; new X { A = r.GetInt32(0) }). Use SqlDb.Str/Int/... helpers for nullable columns.</summary>
        public static List<T> Query<T>(string sql, Func<IDataRecord, T> map, params SqlParameter[] ps)
        {
            using (var c = Open()) return QueryOn(c, null, sql, map, ps);
        }

        /// <summary>First column of first row converted to T (default(T) when no row / NULL).</summary>
        public static T Scalar<T>(string sql, params SqlParameter[] ps)
        {
            using (var c = Open()) return ScalarOn<T>(c, null, sql, ps);
        }

        /// <summary>INSERT/UPDATE/DELETE; returns affected rows.</summary>
        public static int Execute(string sql, params SqlParameter[] ps)
        {
            using (var c = Open()) return ExecuteOn(c, null, sql, ps);
        }

        /// <summary>Run several statements atomically. Commit on normal return, rollback on exception.</summary>
        public static void Transaction(Action<SqlTx> work)
        {
            Transaction<object>(tx => { work(tx); return null; });
        }

        public static T Transaction<T>(Func<SqlTx, T> work)
        {
            using (var c = Open())
            using (var t = c.BeginTransaction())
            {
                try
                {
                    var r = work(new SqlTx(c, t));
                    t.Commit();
                    return r;
                }
                catch
                {
                    try { t.Rollback(); } catch { }
                    throw;
                }
            }
        }

        // ---- null-safe readers for the map functions ----
        public static string Str(IDataRecord r, string col) { int i = r.GetOrdinal(col); return r.IsDBNull(i) ? null : Convert.ToString(r.GetValue(i)); }
        public static int Int(IDataRecord r, string col, int def = 0) { int i = r.GetOrdinal(col); return r.IsDBNull(i) ? def : Convert.ToInt32(r.GetValue(i)); }
        public static int? IntN(IDataRecord r, string col) { int i = r.GetOrdinal(col); return r.IsDBNull(i) ? (int?)null : Convert.ToInt32(r.GetValue(i)); }
        public static decimal? Dec(IDataRecord r, string col) { int i = r.GetOrdinal(col); return r.IsDBNull(i) ? (decimal?)null : Convert.ToDecimal(r.GetValue(i)); }
        public static DateTime? Date(IDataRecord r, string col) { int i = r.GetOrdinal(col); return r.IsDBNull(i) ? (DateTime?)null : Convert.ToDateTime(r.GetValue(i)); }
        /// <summary>SQL TIME column -> "HH:mm".</summary>
        public static string TimeText(IDataRecord r, string col) { int i = r.GetOrdinal(col); return r.IsDBNull(i) ? null : ((TimeSpan)r.GetValue(i)).ToString(@"hh\:mm"); }

        // ---- shared implementation ----
        internal static SqlCommand Cmd(SqlConnection c, SqlTransaction t, string sql, SqlParameter[] ps)
        {
            var cmd = new SqlCommand(sql, c, t) { CommandTimeout = 30 };
            if (ps != null) foreach (var p in ps) cmd.Parameters.Add(p);
            return cmd;
        }

        internal static DataTable QueryOn(SqlConnection c, SqlTransaction t, string sql, SqlParameter[] ps)
        {
            var dt = new DataTable();
            using (var cmd = Cmd(c, t, sql, ps))
            using (var rd = cmd.ExecuteReader()) dt.Load(rd);
            return dt;
        }

        internal static List<T> QueryOn<T>(SqlConnection c, SqlTransaction t, string sql, Func<IDataRecord, T> map, SqlParameter[] ps)
        {
            var list = new List<T>();
            using (var cmd = Cmd(c, t, sql, ps))
            using (var rd = cmd.ExecuteReader())
                while (rd.Read()) list.Add(map(rd));
            return list;
        }

        internal static T ScalarOn<T>(SqlConnection c, SqlTransaction t, string sql, SqlParameter[] ps)
        {
            using (var cmd = Cmd(c, t, sql, ps))
            {
                var o = cmd.ExecuteScalar();
                if (o == null || o == DBNull.Value) return default(T);
                var target = Nullable.GetUnderlyingType(typeof(T)) ?? typeof(T);
                return (T)Convert.ChangeType(o, target);
            }
        }

        internal static int ExecuteOn(SqlConnection c, SqlTransaction t, string sql, SqlParameter[] ps)
        {
            using (var cmd = Cmd(c, t, sql, ps)) return cmd.ExecuteNonQuery();
        }
    }

    /// <summary>Same helpers as SqlDb, bound to one open transaction (see SqlDb.Transaction).</summary>
    public class SqlTx
    {
        private readonly SqlConnection _c;
        private readonly SqlTransaction _t;
        internal SqlTx(SqlConnection c, SqlTransaction t) { _c = c; _t = t; }

        public DataTable Query(string sql, params SqlParameter[] ps) { return SqlDb.QueryOn(_c, _t, sql, ps); }
        public List<T> Query<T>(string sql, Func<IDataRecord, T> map, params SqlParameter[] ps) { return SqlDb.QueryOn(_c, _t, sql, map, ps); }
        public T Scalar<T>(string sql, params SqlParameter[] ps) { return SqlDb.ScalarOn<T>(_c, _t, sql, ps); }
        public int Execute(string sql, params SqlParameter[] ps) { return SqlDb.ExecuteOn(_c, _t, sql, ps); }
    }
}
